// Clean and validate the incoming text
const message = $input.item(0).json;
const text = message.message?.text || '';

// Basic text cleaning
let cleanedText = text
  .trim()
  .replace(/\s+/g, ' ')  // Replace multiple spaces with single space
  .replace(/[^\w\s.,!?;:-]/g, '')  // Remove special characters except basic punctuation
  .replace(/\b(um|uh|like|you know)\b/gi, '')  // Remove filler words
  .trim();

// Capitalize first letter
if (cleanedText) {
  cleanedText = cleanedText.charAt(0).toUpperCase() + cleanedText.slice(1);
}

// Ensure it ends with punctuation
if (cleanedText && !/[.!?]$/.test(cleanedText)) {
  cleanedText += '.';
}

return {
  originalText: text,
  cleanedText: cleanedText,
  wordCount: cleanedText.split(' ').length,
  timestamp: new Date().toISOString(),
  messageId: message.message?.message_id,
  fromUser: message.message?.from?.username || 'unknown'
};

// Format the cleaned text into a blog entry beginning
const data = $input.item(0).json;
const cleanedText = data.cleanedText;

if (!cleanedText || cleanedText.length < 10) {
  throw new Error('Text too short or empty to create a blog entry');
}

// Generate blog entry structure
const blogTitle = generateTitle(cleanedText);
const blogIntro = generateIntroduction(cleanedText);
const blogOutline = generateOutline(cleanedText);

function generateTitle(text) {
  // Extract key concepts for title generation
  const words = text.toLowerCase().split(' ');
  const keyWords = words.filter(word => 
    word.length > 4 && 
    !['about', 'through', 'would', 'could', 'should', 'their', 'there', 'where'].includes(word)
  );

  // Create a title based on the first few key concepts
  const titleWords = keyWords.slice(0, 4).map(word => 
    word.charAt(0).toUpperCase() + word.slice(1)
  );

  return `Exploring ${titleWords.join(' ')}: A Deep Dive into Modern Innovation`;
}

function generateIntroduction(text) {
  return `# Introduction

In today's rapidly evolving technological landscape, new ideas and concepts emerge daily that have the potential to reshape our understanding and approach to complex challenges. ${text}

This blog post will explore this fascinating topic in detail, examining its implications, potential applications, and the broader context within which it operates.`;
}

function generateOutline(text) {
  return `
## Article Outline

1. **Background and Context**
   - Current state of the field
   - Key challenges and opportunities

2. **Core Concepts**
   - Detailed exploration of the main idea
   - Technical considerations

3. **Real-World Applications**
   - Practical implementations
   - Case studies and examples

4. **Future Implications**
   - Potential developments
   - Long-term impact

5. **Conclusion**
   - Key takeaways
   - Next steps for exploration

---

*This blog entry was generated from a Telegram message on ${new Date().toLocaleDateString()}*`;
}

const fullBlogEntry = `# ${blogTitle}

${blogIntro}

${blogOutline}`;

return {
  title: blogTitle,
  fullContent: fullBlogEntry,
  wordCount: fullBlogEntry.split(' ').length,
  originalIdea: cleanedText,
  generatedAt: data.timestamp,
  sourceUser: data.fromUser,
  messageId: data.messageId
};
